INSERT INTO `communities` VALUES (1,'uploads/communities/1783945230_banner__Arjan.webp','Dubai','Arjan is a thriving freehold mixed-use community in Dubailand, developed by Dubai Properties. Known for its peaceful atmosphere, modern residential developments, and family-friendly environment, the community is home to iconic attractions such as Dubai Miracle Garden and Dubai Butterfly Garden. Strategically located at the intersection of Sheikh Mohammed Bin Zayed Road (E311) and Umm Suqeim Street (D63), Arjan offers seamless connectivity to Dubai Hills Estate, Motor City, Jumeirah Village Circle, Dubai Marina, and Downtown Dubai. The area features a wide range of apartments, retail outlets, schools, healthcare facilities, and recreational amenities, making it an attractive destination for both homeowners and investors.',NULL,'uploads/communities/1783945230__Arjan.webp',NULL,1,0,25.0628,55.2393,NULL,NULL,'Arjan',NULL,'arjan',1,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (2,'uploads/communities/1784531522_banner_22.webp','Dubai','Sitting directly south of Downtown Dubai, Business Bay is one of the city\'s most fast-paced, prestigious, and connected mixed-use communities. Built along the glistening Dubai Water Canal, it seamlessly blends high-powered corporate headquarters with luxury high-rise living, waterside dining, and an energetic social scene.',NULL,'uploads/communities/1784531522_22.webp',NULL,1,0,25.1852,55.2740,NULL,NULL,'Business Bay',NULL,'business-bay',2,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (3,'uploads/communities/1786275998_Creek-Haven-DCH-3.webp','Dubai',NULL,NULL,'uploads/communities/1786275998_Creek-Haven-DCH-3.webp',NULL,1,0,NULL,NULL,NULL,NULL,'Creek Harbour',NULL,'creek-harbour',3,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (4,'uploads/communities/1782831333_banner_dow-1.webp','Dubai','Home to the Burj Khalifa and Dubai Mall, Downtown Dubai is the city\'s established cultural and commercial core — a landmark address built around the Dubai Fountain and Sheikh Mohammed bin Rashid Boulevard.',NULL,'uploads/communities/1782831333_dow-1.webp',NULL,1,0,NULL,NULL,NULL,NULL,'Downtown Dubai',NULL,'downtown-dubai',11,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (5,'uploads/communities/1782830822_banner_licensed-image.jfif','Dubai','A waterfront masterplan along the historic Dubai Creek, anchored by a growing skyline and cultural district designed to mature over the next decade — positioned as one of the city\'s defining long-term addresses.',NULL,'uploads/communities/1782830822_licensed-image.jfif',NULL,1,0,25.1950,55.3500,NULL,NULL,'Dubai Creek Harbour',NULL,'dubai-creek-harbour',15,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (6,'uploads/communities/1782830876_banner_unnamed.webp','Dubai','A master-planned green community centred around an 18-hole championship golf course, combining villas, townhouses, and apartments with parks, schools, and retail within a single connected neighbourhood.',NULL,'uploads/communities/1782830876_unnamed.webp',NULL,1,0,25.1080,55.2480,NULL,NULL,'Dubai Hills Estate',NULL,'dubai-hills-estate',16,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (7,'uploads/communities/1783939730_banner_main-dubai-islands-01.jpg','Dubai','Dubai Islands is a premier waterfront master development by Nakheel comprising five interconnected islands along Dubai\'s coastline. The community offers a mix of luxury apartments, villas, townhouses, branded residences, resorts, marinas, golf courses, retail destinations, and pristine beaches. With excellent connectivity to Downtown Dubai, Dubai International Airport, and major business districts, Dubai Islands presents an exceptional lifestyle and investment opportunity for residents and investors alike.',NULL,'uploads/communities/1783939730_main-dubai-islands-01.jpg',NULL,1,0,25.3269,55.3475,NULL,NULL,'Dubai Islands',NULL,'dubai-islands',4,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (8,'uploads/communities/1786276659_MulLtufzpa.jpg','Dubai',NULL,NULL,'uploads/communities/1786276659_MulLtufzpa.jpg',NULL,1,0,NULL,NULL,NULL,NULL,'Dubai Land',NULL,'dubai-land',5,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (9,'uploads/communities/1782830684_banner_827901014.webp','Dubai','A man-made waterfront community lined with high-rise towers, retail, and a continuous promenade along the marina walk — one of Dubai\'s most established and connected addresses.',NULL,'uploads/communities/1782830684_827901014.webp',NULL,1,0,NULL,NULL,NULL,NULL,'Dubai Marina',NULL,'dubai-marina',13,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (10,'uploads/communities/1782831035_banner_Dubai-South.webp','Dubai','Positioned around Al Maktoum International Airport and the Expo 2020 legacy site, Dubai South is a rapidly developing district combining residential, logistics, and aviation-linked infrastructure.',NULL,'uploads/communities/1782831035_Dubai-South.webp',NULL,1,0,24.8970,55.1610,NULL,NULL,'Dubai South',NULL,'dubai-south',18,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (11,'uploads/communities/1786276637_haus_and_haus_blog_Why_invest_in_Palm_Jebel_Ali_864x520_13927277ed.jpg','Dubai',NULL,NULL,'uploads/communities/1786276637_haus_and_haus_blog_Why_invest_in_Palm_Jebel_Ali_864x520_13927277ed.jpg',NULL,1,0,NULL,NULL,NULL,NULL,'Jebel Ali',NULL,'jebel-ali',6,'2026-09-30 07:00:00','2026-09-30 07:00:00');
