INSERT INTO `communities` VALUES (13,'uploads/communities/1782830972_banner_jvc-dubai-vue-aerienne.avif','Dubai','Jumeirah Village Circle is a centrally located, family-oriented community offering a wide mix of apartments, townhouses, and villas at accessible price points, with parks and community facilities throughout.',NULL,'uploads/communities/1782830972_jvc-dubai-vue-aerienne.avif',NULL,1,0,25.0588,55.2080,NULL,NULL,'JVC',NULL,'jvc',17,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (14,'uploads/communities/1782830768_banner_ACoDvrQKLb.jpg','Dubai','The second of Dubai\'s palm-shaped island developments, Palm Jebel Ali is positioned as a larger-scale, lower-density successor to Palm Jumeirah, with a renewed focus on waterfront villas and beachfront living.',NULL,'uploads/communities/1782830768_ACoDvrQKLb.jpg',NULL,1,0,NULL,NULL,NULL,NULL,'Palm Jebel Ali',NULL,'palm-jebel-ali',14,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (15,'uploads/communities/1780932247_banner_inr-banner.png','Dubai','Palm Jumeirah is one of Dubai’s most stunning landmarks and a true marvel of modern engineering. Shaped like a giant palm tree and built by Nakheel, this man-made island is a symbol of luxury and exclusivity. Home to some of the world’s most luxurious villas, stylish apartments, five-star hotels, and world-class attractions, it’s no surprise that Palm Jumeirah is known around the world. With its gorgeous waterfront views, private beaches, and vibrant lifestyle, it captures the essence of Dubai’s innovation and elegance.',NULL,'uploads/communities/1780932247_image_17328781750.jpg',NULL,1,0,NULL,NULL,NULL,NULL,'Palm Jumeirah',NULL,'palm-jumeirah',12,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (16,'uploads/communities/1783941754_banner_images.jfif','Dubai','Rashid Yachts & Marina is a prestigious waterfront community by Emaar, located along Dubai\'s historic coastline. Designed around a world-class marina, the development features luxury apartments, branded residences, vibrant retail outlets, waterfront promenades, fine dining, and leisure attractions. With direct access to the marina and excellent connectivity to Downtown Dubai, DIFC, Dubai International Airport, and Dubai Creek Harbour, Rashid Yachts & Marina offers an exceptional lifestyle for residents, yacht owners, and investors.',NULL,'uploads/communities/1783941754_images.jfif',NULL,1,0,25.2728,55.2747,NULL,NULL,'Rashid Yachts and Marina',NULL,'rashid-yachts-and-marina',8,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (17,'uploads/communities/1784531164_banner_11.jpeg','Dubai',NULL,NULL,'uploads/communities/1784531164_11.jpeg',NULL,1,0,NULL,NULL,NULL,NULL,'The Valley',NULL,'the-valley',9,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `communities` VALUES (18,'uploads/communities/1786275735_banner_yas-and-saadiyat-2024.webp','Dubai',NULL,NULL,'uploads/communities/1786275735_yas-and-saadiyat-2024.webp',NULL,1,0,24.5204,54.6027,NULL,NULL,'Yas Island',NULL,'yas-island',10,'2026-09-30 07:00:00','2026-09-30 07:00:00');
INSERT INTO `blog_posts` VALUES (1,'Quadrant Editorial Team','<p>Dubai Creek Harbour sits at a deliberate intersection — close enough to the city\'s established core to feel connected, far enough to offer space, water, and a skyline of its own.</p><h2>What Sets It Apart</h2><p>The masterplan balances residential towers with cultural and retail infrastructure, designed to mature over a ten-to-fifteen-year horizon rather than arrive complete on day one. For buyers thinking in years rather than months, this matters.</p><p>Quadrant continues to track delivery progress and developer commitments across this community as part of our ongoing market intelligence.</p>','communities','An overview of Dubai Creek Harbour\'s long-term positioning and what it means for considered buyers.',1,'uploads/blog/1782829303_222.jfif',NULL,NULL,'2026-06-29 19:00:00','dubai-creek-harbour-the-next-decade-of-growth','Dubai Creek Harbour: The Next Decade of Growth','2026-06-29 19:00:00','2026-06-29 19:00:00');
INSERT INTO `blog_posts` VALUES (2,'Quadrant Editorial Team','<p>A \"60/40\" payment plan means 60% of the purchase price is paid during construction, with the remaining 40% due on or after handover. It is one of several common structures in the Dubai off-plan market, alongside 80/20 and post-handover plans extending payments beyond completion.</p><h2>Why the Structure Matters</h2><p>The split affects both cash flow planning and risk exposure. A higher pre-handover commitment ties more capital to construction progress; a larger post-handover balance shifts more of that exposure to the buyer\'s ongoing liquidity.</p><p>Neither structure is inherently superior — the right one depends on the buyer\'s own financial position and time horizon. This is precisely the kind of judgment Quadrant works through with clients before any commitment is made.</p>','buyer-guides','A plain-spoken guide to understanding common off-plan payment plan structures in Dubai.',1,'uploads/blog/1782829346_333.png',NULL,NULL,'2026-06-29 19:00:00','reading-a-payment-plan-what-60-40-really-means','Reading a Payment Plan: What 60/40 Really Means','2026-06-29 19:00:00','2026-06-29 19:00:00');
INSERT INTO `blog_posts` VALUES (3,'Quadrant Editorial Team','<p>Dubai\'s off-plan market has matured considerably over the past decade. What was once seen as a higher-risk entry point has become, for many discerning buyers, the most considered way to acquire a stake in the city\'s landmark developments.</p><p>The appeal is structural. Off-plan payment plans allow capital to be deployed in stages rather than as a single lump sum, aligning outflows with construction milestones. This is not a shortcut — it is simply a more deliberate way to build a position.</p><h2>What to Look For</h2><p>Developer track record, escrow account compliance, and realistic handover timelines remain the fundamentals. A landmark name on the hoarding is not, by itself, a reason to commit capital.</p><p>At Quadrant, every off-plan opportunity we present has been assessed against these fundamentals before it reaches a client.</p>','off-plan','A considered look at why off-plan continues to be a disciplined entry point into Dubai real estate.',1,'uploads/blog/1782829281_111.webp',NULL,NULL,'2026-06-29 19:00:00','why-off-plan-remains-dubais-smartest-entry-point','Why Off-Plan Remains Dubai\'s Smartest Entry Point','2026-06-29 19:00:00','2026-06-29 19:00:00');
